func readWordlist(p string) ([]string, error){
	data,err:=os.ReadFile(p)
	if err!=nil{return nil,err}
	var res []string
	for _,l:=range strings.Split(string(data),"\n"){
		l=strings.TrimRight(l,"\r")
		t:=strings.TrimSpace(l)
		if t==""||strings.HasPrefix(t,"#"){continue}
		res=append(res,t)
	}
	return res,nil
}
func readLinesFile(p string) ([]string, error){
	data,err:=os.ReadFile(p)
	if err!=nil{return nil,err}
	var res []string
	for _,l:=range strings.Split(string(data),"\n"){
		l=strings.TrimRight(l,"\r")
		t:=strings.TrimSpace(l)
		if t==""{continue}
		res=append(res,t)
	}
	return res,nil
}

type NotFoundSignature struct{Code int; Size *int; DiffSize *int}
func randString(n int) string{
	letters:=[]rune("ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789")
	b:=make([]rune,n)
	for i:=range b{b[i]=letters[rand.Intn(len(letters))]}
	return string(b)
}
func buildHTTPClient(cfg Config) *http.Client{
	tr:=&http.Transport{TLSClientConfig:&tls.Config{InsecureSkipVerify:cfg.ignoreCert}}
	if cfg.burp{
		pu,_:=url.Parse("http://localhost:8080")
		tr.Proxy=http.ProxyURL(pu)
	}else if cfg.proxy!=""{
		if pu,err:=url.Parse(cfg.proxy);err==nil{tr.Proxy=http.ProxyURL(pu)}
	}else if cfg.noProxy{tr.Proxy=nil}else{tr.Proxy=http.ProxyFromEnvironment}
	return &http.Client{Transport:tr, Timeout:time.Duration(cfg.timeout)*time.Second, CheckRedirect:func(req *http.Request, via []*http.Request) error{return http.ErrUseLastResponse}}
}
func parseHideLengths(vals []string) []struct{low,high int}{
	var r []struct{low,high int}
	for _,v:=range vals{
		if strings.Contains(v,"-"){
			parts:=strings.SplitN(v,"-",2)
			low,err1:=strconv.Atoi(parts[0]); high,err2:=strconv.Atoi(parts[1])
			if err1==nil&&err2==nil{r=append(r,struct{low,high int}{low,high})}
		}else if n,err:=strconv.Atoi(v);err==nil{r=append(r,struct{low,high int}{n,n})}
	}
	return r
}
func isHiddenLength(size int, ranges []struct{low,high int}) bool{
	for _,rr:=range ranges{if size>=rr.low&&size<=rr.high{return true}}
	return false
}
func sanitizeURL(u string) string{
	// Replace % with %25 in path part to allow Go's parser
	idx:=strings.Index(u,"://")
	if idx==-1{
		return strings.ReplaceAll(u,"%", "%25")
	}
	rest:=u[idx+3:]
	slash:=strings.Index(rest,"/")
	if slash==-1{
		return u
	}
	host:=rest[:slash]
	path:=rest[slash:]
	// Avoid double-encoding %25 already? We'll replace % that is not already %25? Simpler: replace "%" with "%25" but first protect existing %25 to avoid double
	// Use placeholder
	path = strings.ReplaceAll(path, "%25", "__PCT25__")
	path = strings.ReplaceAll(path, "%", "%25")
	path = strings.ReplaceAll(path, "__PCT25__", "%25")
	return u[:idx+3]+host+path
}
func detectNotFound(client *http.Client, baseURL, verb, userAgent string, cookies, headers []string, username,password,basicAuth string, verbose int) (NotFoundSignature,bool,error){
	rand.Seed(time.Now().UnixNano())
	randoms:=[]string{randString(10),randString(20),randString(30)}
	type rr struct{code,size int; url string}
	var results []rr
	for _,rnd:=range randoms{
		u:=strings.TrimRight(baseURL,"/")+"/"+rnd
		uSan:=sanitizeURL(u)
		req,_:=http.NewRequest(strings.ToUpper(verb),uSan,nil)
		if userAgent!=""{req.Header.Set("User-Agent",userAgent)}
		if len(cookies)>0{req.Header.Set("Cookie",strings.Join(cookies,"; "))}
		for _,h:=range headers{
			parts:=strings.SplitN(h,":",2)
			if len(parts)==2{req.Header.Set(strings.TrimSpace(parts[0]),strings.TrimSpace(parts[1]))}else if strings.HasSuffix(h,";"){req.Header.Set(strings.TrimSpace(strings.TrimSuffix(h,";")),"")}
		}
		if username!=""||password!=""{req.SetBasicAuth(username,password)}else if basicAuth!=""{req.Header.Set("Authorization",basicAuth)}
		resp,err:=client.Do(req)
		if err!=nil{
			if verbose>=1{fmt.Fprintf(os.Stderr,"Curl error after requesting %s : [%v] %v\n",u,0,err)}else{fmt.Fprintf(os.Stderr,"Curl error after requesting %s : [7] Couldn't connect to server (%v)\n",u,err)}
			continue
		}
		body,_:=io.ReadAll(resp.Body); resp.Body.Close()
		results=append(results,rr{code:resp.StatusCode,size:len(body),url:u})
		if verbose>=2{fmt.Fprintf(os.Stderr,"%s [TRACE] (%d) dirble::request: [src/request.rs:114] Requesting %s\n",time.Now().Format("15:04:05"),2,u)}
	}
	if len(results)==0{return NotFoundSignature{},false,fmt.Errorf("all errored")}
	codeCount:=make(map[int]int)
	for _,r:=range results{codeCount[r.code]++}
	maxC:=0; for _,c:=range codeCount{if c>maxC{maxC=c}}
	var cands []int
	for code,cnt:=range codeCount{if cnt==maxC{cands=append(cands,code)}}
	chosen:=cands[0]
	for _,c:=range cands{if c==404{chosen=404; break}}
	if len(cands)>1{
		for _,r:=range results{
			for _,cand:=range cands{
				if r.code==cand{chosen=cand; goto done}
			}
		}
	done:
	}
	var sizes []int; var urls []string
	for _,r:=range results{if r.code==chosen{sizes=append(sizes,r.size); urls=append(urls,r.url)}}
	if len(sizes)==0{return NotFoundSignature{Code:chosen},true,nil}
	same:=true; for i:=1;i<len(sizes);i++{if sizes[i]!=sizes[0]{same=false; break}}
	if same{s:=sizes[0]; return NotFoundSignature{Code:chosen,Size:&s},true,nil}
	diffs:=make([]int,len(sizes))
	for i:=range sizes{diffs[i]=len(urls[i])-sizes[i]}
	sameDiff:=true; for i:=1;i<len(diffs);i++{if diffs[i]!=diffs[0]{sameDiff=false; break}}
	if sameDiff{d:=diffs[0]; return NotFoundSignature{Code:chosen,DiffSize:&d},true,nil}
	return NotFoundSignature{Code:chosen},true,nil
}
func dedup(in []string) []string{m:=make(map[string]bool); var res []string; for _,s:=range in{if !m[s]{m[s]=true; res=append(res,s)}}; return res}
func writeTxtReport(fname, uri string, found []Found) error{
	f,err:=os.Create(fname); if err!=nil{return err}
	defer f.Close()
	reportURI:=strings.TrimRight(uri,"/")+"/"
	fmt.Fprintf(f,"Dirble Scan Report for %s:\n",reportURI)
	var files, dirs []Found
	for _,ff:=range found{if ff.IsDirectory{dirs=append(dirs,ff)}else{files=append(files,ff)}}
	for _,ff:=range files{
		if ff.RedirectURL!=""{fmt.Fprintf(f,"+ %s (CODE:%d|SIZE:%d|DEST:%s)\n",ff.URL,ff.Code,ff.Size,ff.RedirectURL)}else{fmt.Fprintf(f,"+ %s (CODE:%d|SIZE:%d)\n",ff.URL,ff.Code,ff.Size)}
	}
	if len(files)>0&&len(dirs)>0{fmt.Fprintln(f,"")}
	for i,ff:=range dirs{
		pre:="D"; if ff.IsListable{pre="L"}
		fmt.Fprintf(f,"%s %s (CODE:%d|SIZE:%d)\n",pre,ff.URL,ff.Code,ff.Size)
		if i < len(dirs)-1{fmt.Fprintln(f,"")}else{fmt.Fprintln(f,"")}
	}
	return nil
}
func writeJsonReport(fname string, found []Found) error{
	f,err:=os.Create(fname); if err!=nil{return err}
	defer f.Close()
	var parts []string
	for _,ff:=range found{b,_:=json.Marshal(ff); parts=append(parts,string(b))}
	f.WriteString("["+strings.Join(parts,",\n")+"]")
	return nil
}
func writeXmlReport(fname string, found []Found) error{
	f,err:=os.Create(fname); if err!=nil{return err}
	defer f.Close()
	f.WriteString(xml.Header)
	f.WriteString("<dirble_scan>\n")
	for _,ff:=range found{
		urlEsc:=html.EscapeString(ff.URL)
		redEsc:=html.EscapeString(ff.RedirectURL)
		fmt.Fprintf(f,"<path url=\"%s\" code=\"%d\" content_len=\"%d\" is_directory=\"%t\" is_listable=\"%t\" redirect_url=\"%s\" found_from_listable=\"%t\"/>\n",urlEsc,ff.Code,ff.Size,ff.IsDirectory,ff.IsListable,redEsc,ff.FoundFromListable)
	}
	f.WriteString("</dirble_scan>")
	return nil
}

func main(){
	args:=os.Args[1:]
	if len(args)==0{printHelp(); os.Exit(2)}
	cfg,positional:=parseArgs(args)
	var allUris []string
	allUris=append(allUris,cfg.uris...)
	allUris=append(allUris,positional...)
	if len(allUris)==0{printHelp(); os.Exit(2)}
	var validUris []string
	for _,u:=range allUris{
		p,err:=url.Parse(u)
		if err!=nil||!p.IsAbs(){fmt.Fprintf(os.Stderr,"error: invalid value '%s' for '[uri]': relative URL without a base\n\nFor more information, try '--help'.\n",u); os.Exit(2)}
		validUris=append(validUris,u)
	}
	client:=buildHTTPClient(cfg)
	type UriInfo struct{Original string; Parsed *url.URL; BasicAuth string}
	var uriInfos []UriInfo
	for _,uStr:=range validUris{
		parsed,_:=url.Parse(uStr)
		ba:=""
		if parsed.User!=nil{
			creds:=parsed.User.Username()+":"+func()string{p,_:=parsed.User.Password(); return p}()
			ba="Basic "+base64.StdEncoding.EncodeToString([]byte(creds))
		}
		if cfg.username!=""||cfg.password!=""{
			ba="Basic "+base64.StdEncoding.EncodeToString([]byte(cfg.username+":"+cfg.password))
		}
		uriInfos=append(uriInfos,UriInfo{Original:uStr,Parsed:parsed,BasicAuth:ba})
	}
	var sigs []NotFoundSignature
	var hasSigs []bool
	var validationFailed []bool
	if !cfg.disableValidator && len(cfg.codeWhitelist)==0 {
		for _,ui:=range uriInfos{
			scanBase:=strings.TrimRight(ui.Parsed.String(),"/")+"/"
			s,ok,err:=detectNotFound(client,scanBase,cfg.verb,cfg.userAgent,cfg.cookies,cfg.headers,cfg.username,cfg.password,ui.BasicAuth,cfg.verbose)
			if err!=nil || !ok {
				if !cfg.silent{fmt.Fprintf(os.Stderr,"[WARN] %s errored too often during validation, skipping scanning\n",scanBase)}
				sigs=append(sigs,NotFoundSignature{}); hasSigs=append(hasSigs,false); validationFailed=append(validationFailed,true)
			} else {
				if !cfg.silent{
					if s.Size!=nil{fmt.Printf("[INFO] Detected nonexistent paths for %s are (CODE:%d|SIZE:%d)\n",scanBase,s.Code,*s.Size)}else if s.DiffSize!=nil{fmt.Printf("[INFO] Detected nonexistent paths for %s are (CODE:%d|DIFF_SIZE:%d)\n",scanBase,s.Code,*s.DiffSize)}else{fmt.Printf("[INFO] Detected nonexistent paths for %s are (CODE:%d)\n",scanBase,s.Code)}
					if cfg.maxThreads-2 > cfg.wordlistSplit {
						es:=cfg.maxThreads-2
						if es<1{es=1}
						if es!=cfg.wordlistSplit{fmt.Printf("[INFO] Increasing wordlist-split for initial scan of %s to %d\n",scanBase,es)}
					}
				}
				sigs=append(sigs,s); hasSigs=append(hasSigs,true); validationFailed=append(validationFailed,false)
			}
		}
	} else {
		for range uriInfos{sigs=append(sigs,NotFoundSignature{}); hasSigs=append(hasSigs,false); validationFailed=append(validationFailed,false)}
	}
	wordlistPath:=cfg.wordlistPath
	if wordlistPath==""{wordlistPath="dirble_wordlist.txt"}
	words,err:=readWordlist(wordlistPath)
	if err!=nil{fmt.Fprintf(os.Stderr,"[ERROR] Unable to find default wordlist\n"); os.Exit(0)}
	var prefixes []string
	prefixes=append(prefixes,cfg.prefixes...)
	if cfg.prefixFile!=""{lines,_:=readLinesFile(cfg.prefixFile); prefixes=append(prefixes,lines...)}
	sort.Strings(prefixes); prefixes=dedup(prefixes)
	var extensions []string
	extensions=append(extensions,cfg.extensions...)
	if cfg.extensionFile!=""{lines,_:=readLinesFile(cfg.extensionFile); extensions=append(extensions,lines...)}
	for i,e:=range extensions{if e!=""&&!strings.HasPrefix(e,"."){extensions[i]="."+e}}
	sort.Strings(extensions); extensions=dedup(extensions)
	hideRanges:=parseHideLengths(cfg.hideLengths)
	var bl []int; for _,s:=range cfg.codeBlacklist{if c,err:=strconv.Atoi(s);err==nil{bl=append(bl,c)}}
	var wl []int; for _,s:=range cfg.codeWhitelist{if c,err:=strconv.Atoi(s);err==nil{wl=append(wl,c)}}

	type perHost struct{uri string; found []Found}
	var perHostResults []perHost
	var mu sync.Mutex
	var globalFound []Found

	for idx, uriInfo := range uriInfos {
		if validationFailed[idx]{continue}
		sig:=sigs[idx]
		hasSig:=hasSigs[idx]
		scanBase:=strings.TrimRight(uriInfo.Parsed.String(),"/")+"/"
		maxDepth:=100
		if cfg.maxRecursionDepth!=nil{maxDepth=*cfg.maxRecursionDepth}
		if cfg.disableRecursion{maxDepth=0}
		type Task struct{URL string; Depth int}
		queue:=[]Task{{URL:scanBase,Depth:0}}
		var qMu sync.Mutex
		visited:=map[string]bool{scanBase:true}
		genCands:=func(base string) []string{
			var cands []string
			for _,word:=range words{
				hasPH:=strings.Contains(word,"%EXT%")
				if cfg.extSub{
					if hasPH{
						if !cfg.forceExtension{cands=append(cands,base+strings.ReplaceAll(word,"%EXT%","")); for _,ext:=range extensions{cands=append(cands,base+strings.ReplaceAll(word,"%EXT%",ext))}}else{for _,ext:=range extensions{cands=append(cands,base+strings.ReplaceAll(word,"%EXT%",ext))}}
					}else{
						if !cfg.forceExtension{cands=append(cands,base+word); for _,ext:=range extensions{cands=append(cands,base+word+ext)}}else{for _,ext:=range extensions{cands=append(cands,base+word+ext)}}
					}
				}else{
					if !cfg.forceExtension{cands=append(cands,base+word); for _,ext:=range extensions{cands=append(cands,base+word+ext)}}else{for _,ext:=range extensions{cands=append(cands,base+word+ext)}}
				}
				for _,pre:=range prefixes{
					pword:=pre+word
					hasPH2:=strings.Contains(pword,"%EXT%")
					if cfg.extSub{
						if hasPH2{
							if !cfg.forceExtension{cands=append(cands,base+strings.ReplaceAll(pword,"%EXT%","")); for _,ext:=range extensions{cands=append(cands,base+strings.ReplaceAll(pword,"%EXT%",ext))}}else{for _,ext:=range extensions{cands=append(cands,base+strings.ReplaceAll(pword,"%EXT%",ext))}}
						}else{
							if !cfg.forceExtension{cands=append(cands,base+pword); for _,ext:=range extensions{cands=append(cands,base+pword+ext)}}else{for _,ext:=range extensions{cands=append(cands,base+pword+ext)}}
						}
					}else{
						if !cfg.forceExtension{cands=append(cands,base+pword); for _,ext:=range extensions{cands=append(cands,base+pword+ext)}}else{for _,ext:=range extensions{cands=append(cands,base+pword+ext)}}
					}
				}
			}
			return cands
		}
		var hostFound []Found
		for len(queue)>0{
			qMu.Lock(); task:=queue[0]; queue=queue[1:]; qMu.Unlock()
			if cfg.maxRecursionDepth!=nil && task.Depth > *cfg.maxRecursionDepth{continue}
			if maxDepth==0 && task.Depth>0{continue}
			if task.Depth>maxDepth && maxDepth!=0{continue}
			cands:=genCands(task.URL)
			if cfg.verbose>=1 && !cfg.silent{fmt.Fprintf(os.Stderr,"%s [DEBUG] (%d) dirble::request_thread: Scanning %s\n",time.Now().Format("15:04:05"),5,task.URL)}
			var wg sync.WaitGroup
			type sr struct{origURL, url string; code,size int; redirect string; isDir,isList bool; body string}
			ch:=make(chan sr, len(cands))
			threads:=cfg.maxThreads; if threads<1{threads=1}
			sem:=make(chan struct{},threads)
			for _,cu:=range cands{
				wg.Add(1); sem<-struct{}{}
				go func(u string){
					defer wg.Done(); defer func(){<-sem}()
					if cfg.throttle>0{time.Sleep(time.Duration(cfg.throttle)*time.Millisecond)}
					if cfg.verbose>=2{fmt.Fprintf(os.Stderr,"%s [TRACE] (%d) dirble::request: [src/request.rs:114] Requesting %s\n",time.Now().Format("15:04:05"),5,u)}
					uSan:=sanitizeURL(u)
					req,_:=http.NewRequest(strings.ToUpper(cfg.verb),uSan,nil)
					if cfg.userAgent!=""{req.Header.Set("User-Agent",cfg.userAgent)}
					if len(cfg.cookies)>0{req.Header.Set("Cookie",strings.Join(cfg.cookies,"; "))}
					for _,h:=range cfg.headers{
						parts:=strings.SplitN(h,":",2)
						if len(parts)==2{req.Header.Set(strings.TrimSpace(parts[0]),strings.TrimSpace(parts[1]))}else if strings.HasSuffix(h,";"){req.Header.Set(strings.TrimSpace(strings.TrimSuffix(h,";")),"")}
					}
					if cfg.username!=""||cfg.password!=""{req.SetBasicAuth(cfg.username,cfg.password)}else if uriInfo.BasicAuth!=""{req.Header.Set("Authorization",uriInfo.BasicAuth)}
					resp,err:=client.Do(req)
					if err!=nil{
						fmt.Fprintf(os.Stderr,"Curl error after requesting %s : [7] Couldn't connect to server (%v)\n",u,err)
						return
					}
					body,_:=io.ReadAll(resp.Body); resp.Body.Close()
					code:=resp.StatusCode; size:=len(body); redirect:=""
					if code>=300&&code<400{
						if loc:=resp.Header.Get("Location"); loc!=""{
							bp,_:=url.Parse(u); lp,_:=url.Parse(loc)
							if bp!=nil&&lp!=nil{
								res:=bp.ResolveReference(lp)
								if uriInfo.Parsed.User!=nil&&res.User==nil{res.User=uriInfo.Parsed.User}
								redirect=res.String()
							}else{redirect=loc}
						}
					}
					isDir:=false; isList:=false; dirURL:=u; orig:=u
					if (code==301||code==302||code==307||code==308)&&redirect!=""{
						up,_:=url.Parse(u); rp,_:=url.Parse(redirect)
						if up!=nil&&rp!=nil{
							if rp.Path==up.Path+"/" || (strings.HasSuffix(redirect,"/")&&strings.TrimSuffix(u,"/")==strings.TrimSuffix(redirect,"/")){isDir=true}else if strings.HasSuffix(rp.Path,"/")&&!strings.HasSuffix(up.Path,"/")&&strings.HasPrefix(rp.Path,up.Path){isDir=true}
						}
						if isDir{
							dirURL=redirect
							req2,_:=http.NewRequest(strings.ToUpper(cfg.verb),sanitizeURL(dirURL),nil)
							if cfg.userAgent!=""{req2.Header.Set("User-Agent",cfg.userAgent)}
							if len(cfg.cookies)>0{req2.Header.Set("Cookie",strings.Join(cfg.cookies,"; "))}
							for _,h:=range cfg.headers{parts:=strings.SplitN(h,":",2); if len(parts)==2{req2.Header.Set(strings.TrimSpace(parts[0]),strings.TrimSpace(parts[1]))}}
							if cfg.username!=""||cfg.password!=""{req2.SetBasicAuth(cfg.username,cfg.password)}else if uriInfo.BasicAuth!=""{req2.Header.Set("Authorization",uriInfo.BasicAuth)}
							resp2,err:=client.Do(req2)
							if err==nil{
								b2,_:=io.ReadAll(resp2.Body); resp2.Body.Close()
								code=resp2.StatusCode; size=len(b2); body=b2
								low:=strings.ToLower(string(body))
								if strings.Contains(low,"index of")||strings.Contains(low,"directory listing"){isList=true}
							}
						}
					}else{
						if up,_:=url.Parse(u); up!=nil&&strings.HasSuffix(up.Path,"/")&&code==200{
							isDir=true
							low:=strings.ToLower(string(body))
							if strings.Contains(low,"index of")||strings.Contains(low,"directory listing"){isList=true}
						}
					}
					ch<-sr{origURL:orig,url:dirURL,code:code,size:size,redirect:redirect,isDir:isDir,isList:isList,body:string(body)}
				}(cu)
			}
			wg.Wait(); close(ch)
			for r:=range ch{
				displayURL:=r.url
				if !r.isDir && r.code>=300 && r.code<400 && r.redirect!=""{displayURL=r.origURL}
				if isHiddenLength(r.size,hideRanges){continue}
				if !cfg.showHtaccess && strings.Contains(strings.ToLower(displayURL),".ht") && r.code==403{continue}
				show:=false
				if len(wl)>0{
					for _,c:=range wl{if c==r.code{show=true; break}}
				}else{
					black:=false
					for _,c:=range bl{if c==r.code{black=true; break}}
					if !black{
						if !cfg.disableValidator && hasSig{
							if sig.Code==r.code{
								if sig.Size!=nil{
									if *sig.Size!=r.size{show=true}
								}else if sig.DiffSize!=nil{
									if r.size!=len(r.url)-*sig.DiffSize{show=true}
								}
							}else{show=true}
						}else{show=true}
					}
				}
				if !show{
					if cfg.verbose>=2{fmt.Fprintf(os.Stderr,"%s [TRACE] (%d) dirble::request_thread: [src/request_thread.rs:179] [%s]: matches Not Found condition\n",time.Now().Format("15:04:05"),5,displayURL)}
					continue
				}
				f:=Found{URL:displayURL,Code:r.code,Size:r.size,IsDirectory:r.isDir,IsListable:r.isList}
				if r.code>=300&&r.code<400&&r.redirect!=""&&!r.isDir{f.RedirectURL=r.redirect}
				hostFound=append(hostFound,f)
				mu.Lock(); globalFound=append(globalFound,f); mu.Unlock()
				if !cfg.silent{
					prefix:="+"
					if r.isDir{
						if r.isList{prefix="L"}else{prefix="D"}
					}
					if f.RedirectURL!=""{
						fmt.Printf("%s %s (CODE:%d|SIZE:%d|DEST:%s)\n",prefix,displayURL,r.code,r.size,f.RedirectURL)
					}else{
						fmt.Printf("%s %s (CODE:%d|SIZE:%d)\n",prefix,displayURL,r.code,r.size)
					}
				}
				if r.isDir{
					if (r.code==401&&!cfg.scan401)||(r.code==403&&!cfg.scan403){}else{
						qMu.Lock()
						if !visited[displayURL]{
							visited[displayURL]=true
							if cfg.maxRecursionDepth==nil||task.Depth+1<=*cfg.maxRecursionDepth{
								if !cfg.disableRecursion{
									if r.isList&&!cfg.scanListable{}else{queue=append(queue,Task{URL:displayURL,Depth:task.Depth+1})}
								}
							}
						}
						qMu.Unlock()
					}
				}
				if cfg.scrapeListable&&r.isList{
					re:=regexp.MustCompile(`href=["']([^"']+)["']`)
					for _,m:=range re.FindAllStringSubmatch(r.body,-1){
						href:=m[1]
						if strings.HasPrefix(href,"http://")||strings.HasPrefix(href,"https://")||strings.HasPrefix(href,"//"){continue}
						var newURL string
						if strings.HasPrefix(href,"/"){
							bp,_:=url.Parse(displayURL)
							newURL=fmt.Sprintf("%s://%s%s",bp.Scheme,bp.Host,href)
						}else{
							base:=displayURL
							if !strings.HasSuffix(base,"/"){base+="/"}
							newURL=base+href
						}
						reqS,_:=http.NewRequest(strings.ToUpper(cfg.verb),sanitizeURL(newURL),nil)
						if cfg.userAgent!=""{reqS.Header.Set("User-Agent",cfg.userAgent)}
						if len(cfg.cookies)>0{reqS.Header.Set("Cookie",strings.Join(cfg.cookies,"; "))}
						for _,h:=range cfg.headers{parts:=strings.SplitN(h,":",2); if len(parts)==2{reqS.Header.Set(strings.TrimSpace(parts[0]),strings.TrimSpace(parts[1]))}}
						if cfg.username!=""||cfg.password!=""{reqS.SetBasicAuth(cfg.username,cfg.password)}else if uriInfo.BasicAuth!=""{reqS.Header.Set("Authorization",uriInfo.BasicAuth)}
						respS,err:=client.Do(reqS)
						if err!=nil{continue}
						bS,_:=io.ReadAll(respS.Body); respS.Body.Close()
						sz:=len(bS); cd:=respS.StatusCode; redir:=""
						if cd>=300&&cd<400{
							if loc:=respS.Header.Get("Location"); loc!=""{
								bp,_:=url.Parse(newURL); lp,_:=url.Parse(loc)
								if bp!=nil&&lp!=nil{
									res:=bp.ResolveReference(lp)
									if uriInfo.Parsed.User!=nil&&res.User==nil{res.User=uriInfo.Parsed.User}
									redir=res.String()
								}else{redir=loc}
							}
						}
						fScrape:=Found{URL:newURL,Code:cd,Size:sz,IsDirectory:strings.HasSuffix(newURL,"/"),RedirectURL:redir,FoundFromListable:true}
						showScrape:=true
						if isHiddenLength(sz,hideRanges){showScrape=false}
						if !cfg.showHtaccess&&strings.Contains(strings.ToLower(newURL),".ht")&&cd==403{showScrape=false}
						if len(wl)>0{
							ok:=false; for _,c:=range wl{if c==cd{ok=true; break}}; if !ok{showScrape=false}
						}else{
							for _,c:=range bl{if c==cd{showScrape=false; break}}
							if showScrape&&!cfg.disableValidator&&hasSig{
								if sig.Code==cd{
									if sig.Size!=nil{if *sig.Size==sz{showScrape=false}}else if sig.DiffSize!=nil{if sz==len(newURL)-*sig.DiffSize{showScrape=false}}else{showScrape=false}
								}
							}
						}
						if showScrape{
							hostFound=append(hostFound,fScrape)
							mu.Lock(); globalFound=append(globalFound,fScrape); mu.Unlock()
							if !cfg.silent{
								pre:="+"
								if fScrape.IsDirectory{pre="D"}
								if redir!=""&&!strings.HasSuffix(newURL,"/"){fmt.Printf("%s %s (CODE:%d|SIZE:%d|DEST:%s)\n",pre,newURL,cd,sz,redir)}else{fmt.Printf("%s %s (CODE:%d|SIZE:%d)\n",pre,newURL,cd,sz)}
							}
						}
					}
				}
			}
		}
		perHostResults=append(perHostResults,perHost{uri:scanBase,found:hostFound})
	}
	if cfg.silent{
		for _,ph:=range perHostResults{
			for _,ff:=range ph.found{
				pre:="+"; if ff.IsDirectory{if ff.IsListable{pre="L"}else{pre="D"}}
				if ff.RedirectURL!=""{fmt.Printf("%s %s (CODE:%d|SIZE:%d|DEST:%s)\n",pre,ff.URL,ff.Code,ff.Size,ff.RedirectURL)}else{fmt.Printf("%s %s (CODE:%d|SIZE:%d)\n",pre,ff.URL,ff.Code,ff.Size)}
			}
		}
	}
	if cfg.outputFile!=""{
		f,_:=os.Create(cfg.outputFile)
		for _,ph:=range perHostResults{
			repURI:=strings.TrimRight(ph.uri,"/")+"/"
			fmt.Fprintf(f,"Dirble Scan Report for %s:\n",repURI)
			var files,dirs []Found
			for _,ff:=range ph.found{if ff.IsDirectory{dirs=append(dirs,ff)}else{files=append(files,ff)}}
			for _,ff:=range files{
				if ff.RedirectURL!=""{fmt.Fprintf(f,"+ %s (CODE:%d|SIZE:%d|DEST:%s)\n",ff.URL,ff.Code,ff.Size,ff.RedirectURL)}else{fmt.Fprintf(f,"+ %s (CODE:%d|SIZE:%d)\n",ff.URL,ff.Code,ff.Size)}
			}
			if len(files)>0&&len(dirs)>0{fmt.Fprintln(f,"")}
			for i,ff:=range dirs{
				pre:="D"; if ff.IsListable{pre="L"}
				fmt.Fprintf(f,"%s %s (CODE:%d|SIZE:%d)\n",pre,ff.URL,ff.Code,ff.Size)
				if i < len(dirs)-1{fmt.Fprintln(f,"")}else{fmt.Fprintln(f,"")}
			}
			fmt.Fprintln(f,"")
		}
		f.Close()
	}
	if cfg.jsonFile!=""{writeJsonReport(cfg.jsonFile,globalFound)}
	if cfg.xmlFile!=""{writeXmlReport(cfg.xmlFile,globalFound)}
	if cfg.outputAll!=""{
		baseTrim:=cfg.outputAll
		for _,suf:=range []string{".txt",".json",".xml"}{if strings.HasSuffix(baseTrim,suf){baseTrim=strings.TrimSuffix(baseTrim,suf); break}}
		fnameTxt:=baseTrim+".txt"
		if !strings.HasSuffix(cfg.outputAll,".txt")&&!strings.HasSuffix(cfg.outputAll,".json")&&!strings.HasSuffix(cfg.outputAll,".xml"){
			fnameTxt=cfg.outputAll+".txt"
			writeJsonReport(cfg.outputAll+".json",globalFound)
			writeXmlReport(cfg.outputAll+".xml",globalFound)
		}else{
			writeJsonReport(baseTrim+".json",globalFound)
			writeXmlReport(baseTrim+".xml",globalFound)
		}
		f,_:=os.Create(fnameTxt)
		for _,ph:=range perHostResults{
			repURI:=strings.TrimRight(ph.uri,"/")+"/"
			fmt.Fprintf(f,"Dirble Scan Report for %s:\n",repURI)
			var files,dirs []Found
			for _,ff:=range ph.found{if ff.IsDirectory{dirs=append(dirs,ff)}else{files=append(files,ff)}}
			for _,ff:=range files{
				if ff.RedirectURL!=""{fmt.Fprintf(f,"+ %s (CODE:%d|SIZE:%d|DEST:%s)\n",ff.URL,ff.Code,ff.Size,ff.RedirectURL)}else{fmt.Fprintf(f,"+ %s (CODE:%d|SIZE:%d)\n",ff.URL,ff.Code,ff.Size)}
			}
			if len(files)>0&&len(dirs)>0{fmt.Fprintln(f,"")}
			for i,ff:=range dirs{
				pre:="D"; if ff.IsListable{pre="L"}
				fmt.Fprintf(f,"%s %s (CODE:%d|SIZE:%d)\n",pre,ff.URL,ff.Code,ff.Size)
				if i < len(dirs)-1{fmt.Fprintln(f,"")}else{fmt.Fprintln(f,"")}
			}
			fmt.Fprintln(f,"")
		}
		f.Close()
	}
}
GO
go build -o executable main.go && echo built ok
